INSERT INTO `club_content` (`id`, `content_type`, `scene`, `title`, `subtitle`, `image`, `body_text`, `target_url`, `popup_enabled`, `start_at`, `end_at`, `style_json`, `sort_no`, `status`, `created_at`, `updated_at`) VALUES (1,'document','merchant-agreement','送给每一位老板的权益','服务规则请仔细阅读','','一、申请人应提供真实、准确、完整的主体及联系方式。\n二、平台审核通过后方可建立商家身份，商家与陪玩身份互斥。\n三、商品、价格、库存和服务说明必须真实有效。\n四、订单履约、售后、退款、结算和佣金以平台有效规则及订单记录为准。\n五、提交申请时系统记录协议版本和同意时间。','',0,NULL,NULL,NULL,0,'active','2026-09-16 13:01:09','2026-09-16 13:01:12');
INSERT INTO `club_content` (`id`, `content_type`, `scene`, `title`, `subtitle`, `image`, `body_text`, `target_url`, `popup_enabled`, `start_at`, `end_at`, `style_json`, `sort_no`, `status`, `created_at`, `updated_at`) VALUES (6,'document','about','关于我们','品奢电竞','','我们专注于提供清晰、可靠的线上娱乐服务体验。','',0,NULL,NULL,'{}',1,'active','2026-09-16 13:01:12','2026-09-16 13:01:12');
INSERT INTO `club_content` (`id`, `content_type`, `scene`, `title`, `subtitle`, `image`, `body_text`, `target_url`, `popup_enabled`, `start_at`, `end_at`, `style_json`, `sort_no`, `status`, `created_at`, `updated_at`) VALUES (7,'document','agreement','用户协议','用户服务协议','','品奢电竞用户服务协议\n版本日期：2026年9月10日；生效日期：本协议正式公布之日。\n一、运营主体与联系\n品奢电竞小程序由绵阳市涪城区品奢电竞科技网咖(个人独资)运营。客服、投诉及账号事项联系邮箱：m19915375856@163.com，您也可以通过小程序内在线客服联系。请认真阅读年龄限制、服务内容、支付退款及争议处理条款，充分理解后决定是否接受。\n二、服务对象与账号\n本平台仅面向年满18周岁的人员提供服务。购买服务的用户和申请成为陪玩服务人员的人员均应年满18周岁，未成年人不得注册、购买或提供服务。\n您应提供真实、准确、有效的账号及履约信息，不得冒用身份、出租出借账号或协助未成年人绕过限制。年龄声明不等于平台已对所有用户完成身份核验；在身份认证及服务人员审核场景，平台将按相应规则审核必要资料。\n账号安全及履约所需信息按隐私政策和具体授权提示处理。请勿向他人提供登录密码、验证码或支付密码。\n三、服务与订单\n平台提供商品页面明确说明的线上游戏陪玩等服务。服务内容、时长、规格、价格、负责服务人员及其他约定，以您下单确认的商品说明和订单为准。平台及服务人员作出的明确承诺应依法履行；除明确约定外，不当然保证游戏胜负、排名等结果。\n下单前请核对内容，填写准确的游戏ID、昵称和有效联系方式。付款不代表服务已经实际开始，服务开始应结合约定、实际履行及订单记录确定。未经您同意，不得擅自更改服务内容、任意加价或降低质量。无法按约服务时，平台应协助处理。\n四、支付与余额\n请通过平台提供的正规渠道支付，金额及优惠以订单展示为准。如使用充值或余额功能，请先核对充值金额、赠送条件和适用范围。余额不是理财产品，不承诺收益。\n未消费充值款可联系客服申请核实处理。赠送权益结合已明确告知的规则处理，不得排除法定权利。\n五、取消与退款\n服务开始前：可从订单售后入口或联系客服申请退款，经核实尚未实际开始服务的，退还该订单实际支付款项。\n服务开始后或正在服务中：请联系在线客服，提供订单编号、原因及必要记录。平台结合订单约定、已履行服务和责任情况处理，可包括继续履行、补救或依法退款，不实行开始后一律不退款。\n服务完成后：如存在未按约履行、质量问题或其他争议，仍可申请售后，不因订单显示已完成而丧失法定权利。\n因平台或服务人员原因无法履约的，不得无理拒绝或拖延处理。退款审核同意不等于资金已到账，以支付渠道或账户记录为准；异常时平台协助核查。退款原则上按原支付方式退回，确需其他方式应事先说明并取得确认。\n六、行为规范\n双方应文明沟通，不得实施骚扰、辱骂、歧视、诈骗、赌博、色情交易、恶意刷单或侵犯他人权益的行为。不得要求提供与正常服务无关的游戏账号密码、支付密码等，不得使用外挂或要求实施违法及违反游戏规则的行为。\n平台可对涉嫌违规行为核实并采取必要限制措施，同时提供申诉渠道。限制账号不免除未完成订单、资金及售后的处理责任。\n七、评价、收益及提现\n用户可对真实订单客观评价，不得发布虚假信息或泄露他人隐私。平台不得仅因评价不利而无正当理由删除真实评价。\n服务人员收益、结算和提现条件以事先明确告知的规则及实际订单记录为准。退款、争议或结算调整应说明原因及依据，不得任意扣减依法取得的收益。提交或批准提现不等于实际到账。\n八、注销与争议\n您可以通过上述邮箱或客服申请注销，平台核验身份并协助处理未完成订单、账户资金及争议，不设置不合理障碍。注销涉及的信息处理见隐私政策。\n争议可先协商，协商不成可依法投诉、申请调解或向有管辖权的人民法院起诉。本协议不排除或限制消费者法定权利，与法律强制性规定不一致的，以法律为准。\n九、更新\n协议重要变更应显著提示并依法取得必要同意，不以新规则追溯减损已经成立订单的合法权益。','',0,NULL,NULL,'{}',1,'active','2026-09-16 13:01:12','2026-09-16 13:05:36');
INSERT INTO `club_content` (`id`, `content_type`, `scene`, `title`, `subtitle`, `image`, `body_text`, `target_url`, `popup_enabled`, `start_at`, `end_at`, `style_json`, `sort_no`, `status`, `created_at`, `updated_at`) VALUES (8,'document','privacy','隐私政策','个人信息保护说明','','品奢电竞隐私政策\n版本日期：2026年9月10日；生效日期：本政策正式公布之日。\n一、处理者与联系方式\n个人信息处理者为绵阳市涪城区品奢电竞科技网咖(个人独资)。隐私权利申请和投诉邮箱：m19915375856@163.com。\n本政策说明个人信息处理目的、范围和权利行使方式。具体授权结合实际功能提示进行，不以同意本政策代替所有单独授权。\n二、信息种类与用途\n注册登录：处理账号UID、微信登录标识、登录凭证及必要登录记录，用于识别账号、保持登录和保障安全。设置手机号账号或订单联系时，处理您填写或经微信授权提供的手机号；设置密码时处理相应密码验证信息。\n资料与互动：处理您主动设置的昵称、头像、性别、生日、城市及收藏、评价、通知偏好。非履约必要的资料不应作为浏览公开内容的必要条件。\n订单履行：处理商品规格、订单编号、游戏ID、游戏昵称、联系人、联系电话、备注、服务状态、评价和售后材料，用于下单、联系、履约及争议处理。请勿在备注或图片中提交无关敏感信息或他人隐私。\n支付与结算：处理订单金额、支付方式、交易编号及状态、余额与资金流水、退款和提现记录，用于交易、对账和结算。微信支付由相应支付服务提供方处理；不要向客服提供支付密码、银行卡密码或验证码。\n身份认证及打手申请：处理主动提交的真实姓名、身份证号码、联系电话、服务介绍及必要申请材料，用于认证及入驻审核。已有认证资料可能用于后续入驻审核。身份证号码属于敏感个人信息，泄露或滥用可能影响身份和财产安全。提交前单独说明并取得同意；拒绝后不提交本次认证或申请，不影响不依赖该信息的公开浏览功能。记录同意场景、版本及时间用于证明授权。\n图片与语音：处理您主动选择或录制的头像、售后图片、服务介绍语音。调用相机、麦克风或保存图片等权限时由您决定是否授权。\n必要日志：为故障排查和安全防护处理必要IP地址、请求时间、接口访问和异常记录。\n三、权限选择\n您可拒绝与当前功能无关的权限。拒绝必要信息可能使对应功能无法完成，不应阻止不依赖该信息的功能。可在微信相关设置管理权限，撤回不影响撤回前合法处理，但可能影响后续对应功能。\n四、提供、公开与第三方处理\n我们不出售个人信息。为履约，仅向负责订单的服务人员提供必要游戏资料、联系方式及订单内容，不向普通用户公开身份证号码、密码或支付凭证。\n服务人员对外展示的昵称、头像、性别、年龄、城市、介绍、语音及接单状态，应以其主动提交并确认公开的资料为基础。\n微信平台相关服务：微信登录使用登录凭证及账号标识；手机号授权使用您确认授权的手机号相关信息；具体处理以微信功能页面及相应隐私告知为准。\n微信支付相关服务：支付、退款及适用的资金处理使用订单、金额、交易标识、状态和必要收款信息；具体以相应支付或收款页面的告知为准。平台不因您同意本政策而取得支付密码。\n技术服务：部署、存储和传输服务涉及服务器端信息处理。委托服务方时限定处理目的和范围并履行必要监督，不允许擅自另作他用。\n需要向其他独立处理者提供个人信息的，依法事先告知接收方、目的、信息种类等并在需要时取得单独同意。新增第三方或改变处理范围时更新相应告知，不用本政策作无限授权。\n五、保存与保护\n仅在实现目的所必要的期限内保存，法律对交易、财务等记录另有要求的依法保存。处理目的已实现、信息不再必要或符合其他删除条件时，依法删除或匿名化；依法暂不能删除的，仅作必要保存和安全保护。\n采取与风险相适应的访问控制、权限管理、传输保护及备份措施。发生安全事件时依法补救，并履行通知和报告义务。\n六、权利申请与注销受理\n可通过资料设置或联系邮箱申请查阅、复制、更正、补充、删除信息、撤回同意、注销账号及了解处理规则。实名资料如需更正，可联系人工核实，不因页面不能直接修改而拒绝受理。\n邮件请说明申请事项和账号UID或便于核对的账号信息；不要直接发送完整身份证照片、密码或验证码。平台按必要范围核验身份，告知处理结果；不能满足申请的说明理由。\n注销通过客服或邮箱人工受理，不表示已有自动注销按钮。平台协助结清未完成订单、余额、提现和争议事项，不设置不合理障碍；注销后除依法应保留的信息外，依法删除或匿名化。\n七、未成年人\n本平台仅面向年满18周岁人员，不向未成年人开放注册、购买或入驻。发现未成年人使用或提交信息，可通过邮箱联系，平台核实后停止相应服务并依法处理信息、订单及款项。本条不表示已经对所有用户自动完成年龄核验。\n八、更新\n处理目的、种类或提供范围发生重要变化时，显著告知并依法取得必要同意。疑问及权利申请请联系 m19915375856@163.com。','',0,NULL,NULL,'{}',1,'active','2026-09-16 13:01:12','2026-09-16 13:05:36');
INSERT INTO `club_content` (`id`, `content_type`, `scene`, `title`, `subtitle`, `image`, `body_text`, `target_url`, `popup_enabled`, `start_at`, `end_at`, `style_json`, `sort_no`, `status`, `created_at`, `updated_at`) VALUES (9,'document','filing','备案资质','平台资质说明','','备案与经营资质信息以后台最新配置为准。','',0,NULL,NULL,'{}',1,'active','2026-09-16 13:01:12','2026-09-16 13:01:12');
